def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    yesterday_bids = []
    rich_pressure = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 700:
                rich_pressure += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    yesterday_bids.append(float(prev.get('bid', 0)))
                except Exception:
                    pass

    if not alive_opponents:
        return float(min(budget, 18.0 if hp > 3 else 40.0))

    highest_prev = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    elif hp <= 6:
        urgency += 0.2

    if no_water_days >= 2:
        urgency += 0.9
    elif no_water_days >= 1:
        urgency += 0.35

    urgency += scarcity * 0.7

    if day >= 8:
        urgency += 0.2

    if highest_prev >= 120:
        market_mode = 'irrational_high'
    elif highest_prev >= 80:
        market_mode = 'high'
    elif highest_prev >= 45:
        market_mode = 'medium'
    else:
        market_mode = 'low'

    if urgency >= 1.4:
        bid = 118.0 + 18.0 * scarcity
        if rich_pressure >= 2:
            bid += 8.0
    elif urgency >= 0.8:
        if market_mode == 'irrational_high':
            bid = 86.0 + 10.0 * scarcity
        elif market_mode == 'high':
            bid = max(72.0, min(98.0, avg_prev + 4.0))
        elif market_mode == 'medium':
            bid = max(58.0, highest_prev + 2.5)
        else:
            bid = 52.0 + 10.0 * scarcity
    else:
        if market_mode == 'irrational_high':
            bid = 24.0 + 8.0 * scarcity
        elif market_mode == 'high':
            bid = 34.0 + 8.0 * scarcity
        elif market_mode == 'medium':
            bid = 42.0 + 6.0 * scarcity
        else:
            bid = 38.0 + 5.0 * scarcity

    if supply <= 16:
        bid += 8.0
    elif supply >= 23 and urgency < 0.8:
        bid -= 6.0

    safe_cap = budget
    if hp > 6 and no_water_days == 0:
        safe_cap = min(safe_cap, budget * 0.28 + DAILY_SALARY * 0.35)
    elif hp > 4:
        safe_cap = min(safe_cap, budget * 0.42 + DAILY_SALARY * 0.5)
    else:
        safe_cap = min(safe_cap, budget * 0.75 + DAILY_SALARY * 0.8)

    if day >= 9 and hp <= 4:
        safe_cap = budget

    bid = min(bid, safe_cap)
    bid = max(0.0, min(budget, bid))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not yesterday_bids:
        return min(my_status['budget'], DAILY_SALARY * 0.6)

    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    if supply < WATER_REQ * 1.5:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    if avg_prev_bid > DAILY_SALARY * 1.2:
        return min(my_status['budget'], DAILY_SALARY * 0.7)

    return min(my_status['budget'], max(DAILY_SALARY * 0.55, avg_prev_bid * 0.95))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = {oid: o for oid, o in opponents_status.items() if o['alive']}

    # Get yesterday's bids for alive opponents
    prev_bids = []
    for opp in alive_opponents.values():
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    # Determine urgency
    urgent = hp <= 2 or no_water_days >= 1

    # Base bid: adapt to yesterday's highest pressure
    if prev_bids:
        highest_prev = max(prev_bids)
        # Supply factor: more supply = lower competition
        if supply >= 20:
            # Can afford to be more conservative
            if urgent:
                base = min(budget, DAILY_SALARY * 0.95)
            else:
                base = min(budget, max(DAILY_SALARY * 0.45, highest_prev * 0.8))
        else:
            # Supply low, need to compete
            if urgent:
                base = min(budget, max(DAILY_SALARY * 0.95, highest_prev + 0.5))
            else:
                base = min(budget, max(DAILY_SALARY * 0.5, highest_prev + 1.0))
    else:
        # No previous data (first day or all opponents died)
        if urgent:
            base = min(budget, DAILY_SALARY * 0.9)
        elif supply >= 20:
            base = min(budget, DAILY_SALARY * 0.4)
        else:
            base = min(budget, DAILY_SALARY * 0.6)

    # Ensure we bid at least something and not exceed budget
    bid = max(1.0, min(budget, base))
    # Round to avoid extreme decimals
    return round(bid, 2)
